class Solution {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String entrada = in.nextLine();
        String[] placas = entrada.split(",");

        // Radix Sort - processando da direita para esquerda (ordem crescente)
        for (int indice = 7; indice > 3; indice--) {
            placas = countingSortPorDigito(placas, indice);
        }

        System.out.println(String.join(", ", placas));
    }

    private static String[] countingSortPorDigito(String[] array, int indice) {
        int n = array.length;
        String[] resultado = new String[n];
        int[] contador = new int[10];

        // Contagem
        for (int i = 0; i < n; i++) {
            int digito = Character.getNumericValue(array[i].charAt(indice));
            contador[digito]++;
        }

        // Soma cumulativa
        for (int i = 1; i < 10; i++) {
            contador[i] += contador[i-1];
        }

        // Construção do array ordenado (ordem reversa para estabilidade)
        for (int i = n - 1; i >= 0; i--) {
            int digito = Character.getNumericValue(array[i].charAt(indice));
            resultado[contador[digito] - 1] = array[i];
            contador[digito]--;
        }

        return resultado;
    }
}
