class Solution {

    public static void countingSortByPairs(int[] arr, int pairIndex, int d) {
        int n = arr.length;
        int[] output = new int[n];
        int[] count = new int[100]; // 00 a 99

        // Extrair pares de dígitos
        for (int i = 0; i < n; i++) {
            int pair = extractPair(arr[i], pairIndex, d);
            count[pair]++;
        }

        // Soma cumulativa
        for (int i = 1; i < 100; i++) {
            count[i] += count[i - 1];
        }

        // Construção do array ordenado (ordem inversa para estabilidade)
        for (int i = n - 1; i >= 0; i--) {
            int pair = extractPair(arr[i], pairIndex, d);
            output[count[pair] - 1] = arr[i];
            count[pair]--;
        }

        // Copiar de volta
        for (int i = 0; i < n; i++) {
            arr[i] = output[i];
        }
    }

    public static int extractPair(int num, int pairIndex, int d) {
        // Determinar posição dos dois dígitos
        int rightShift = d - pairIndex * 2;
        if (rightShift < 0) rightShift = 0;

        // Extrair os dois dígitos
        int shifted = num / (int)Math.pow(10, rightShift);
        return shifted % 100; // Pegar últimos 2 dígitos
