class TabelaHash {
    private ArrayList<Pair>[] tabela;

    @SuppressWarnings("unchecked")
    TabelaHash(int tamanho) {
        tabela = new ArrayList[tamanho];
        for (int i = 0; i < tamanho; i++) {
            tabela[i] = new ArrayList<Pair>();
        }
    }

    private int hash(int chave) {
        return chave % tabela.length;
    }

    void put(int chave, String valor) {
        int pos = hash(chave);
        ArrayList<Pair> lista = tabela[pos];

        // Verifica se já existe a chave
        for (int i = 0; i < lista.size(); i++) {
            if (lista.get(i).chave == chave) {
                lista.get(i).valor = valor; // Atualiza valor
                return;
