class TabelaHash {
    private ArrayList<Pair>[] tabela;

    @SuppressWarnings("unchecked")
    public TabelaHash(int size) {
        tabela = new ArrayList[size];
        for (int i = 0; i < size; i++) {
            tabela[i] = new ArrayList<>();
        }
    }

    private int hash(int key) {
        return key % tabela.length;
    }

    public void put(int key, String value) {
        int pos = hash(key);
        ArrayList<Pair> lista = tabela[pos];

        for (Pair par : lista) {
            if (par.key == key) {
                par.value = value;
                return;
            }
        }

        lista.add(new Pair(key, value));
    }

    public boolean remove(int key) {
        int pos = hash(key);
        ArrayList<Pair> lista = tabela[pos];

        for (int i = 0; i < lista.size(); i++) {
            if (lista.get(i).key == key) {
                lista.remove(i);
                return true;
            }
        }

        return false;
    }

    public int[] keys() {
        ArrayList<Integer> chaves = new ArrayList<>();
        for (ArrayList<Pair> lista : tabela) {
            for (Pair par : lista) {
                chaves.add(par.key);
            }
        }
        Collections.sort(chaves);

        int[] resultado = new int[chaves.size()];
        for (int i = 0; i < resultado.length; i++) {
            resultado[i] = chaves.get(i);
        }
        return resultado;
    }

    public String[] values() {
        ArrayList<String> valores = new ArrayList<>();
        for (ArrayList<Pair> lista : tabela) {
            for (Pair par : lista) {
                valores.add(par.value);
            }
        }
        Collections.sort(valores);

        return valores.toArray(new String[0]);
    }

    @Override
    public String toString() {
        return Arrays.toString(tabela);
    }
}

class Pair {
    int key;
    String value;

    public Pair(int key, String value) {
        this.key = key;
        this.value = value;
    }

    @Override
    public String toString() {
        return "<" + key + ", " + value + ">";
    }
}
