        Node aux = root;
        int out = -1;

        while (aux != null) {

            if (Math.abs(v - aux.value) < md) {
                md = Math.abs(v - aux.value);
                out = aux.value;
            }


            if (aux.value < v)
                aux = aux.left;
            else if (aux.value == v) return v;
            else aux = aux.right;

        }

        return out;

    }

