import java.util.Scanner;

class No {
    int valor;
    No esquerda, direita;

    public No(int valor) {
        this.valor = valor;
        this.esquerda = null;
        this.direita = null;
    }
}

class BST {
    private No raiz;

    public BST() {
        this.raiz = null;
    }

    public void adicionar(int valor) {
        if (this.raiz == null) {
            this.raiz = new No(valor);
        } else {
            this.adicionar(this.raiz, valor);
        }
    }

    private void adicionar(No no, int valor) {
        if (valor < no.valor) {
            if (no.esquerda == null) {
                no.esquerda = new No(valor);
            } else {
                this.adicionar(no.esquerda, valor);
            }
        } else if (valor > no.valor) {
            if (no.direita == null) {
                no.direita = new No(valor);
            } else {
                this.adicionar(no.direita, valor);
            }
        }
    }

    public int contarInternos() {
        return this.contarInternos(this.raiz);
    }

    private int contarInternos(No no) {
        if (no == null) {
            return 0;
        }

        // Se for uma folha (não tem filhos), retorna 0
        if (no.esquerda == null && no.direita == null) {
            return 0;
        }

        // Se é nó interno, conta 1 + os internos das subárvores
        return 1 + this.contarInternos(no.esquerda) + this.contarInternos(no.direita);
    }

    public static void main(String[] args) {
