    private static void partition(int[] arr, int pivotIndex) {
        int pivot = arr[pivotIndex];
        int left = 0;
        int right = arr.length - 1;

        while (left < right) {
            while (left < arr.length && arr[left] <= pivot) left++;
            while (right >= 0 && arr[right] > pivot) right--;

