import java.util.Scanner;

class Solution {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        String input = scan.nextLine();

        String[] strArray = input.split(" ");
        int[] intArray = new int[strArray.length];
        for (int i = 0; i < strArray.length; i++) {
            intArray[i] = Integer.parseInt(strArray[i]);
        }

        int pivot = intArray[0];
        int cont = 1; // O pivot é o 1º menor entre os elementos menores ou iguais a ele

        for (int i = 1; i < intArray.length; i++) {
            if (intArray[i] < pivot) {
                cont++;
            }
        }

        // Reorganização (particionamento) em torno do pivot
        int left = 1;
        int right = intArray.length - 1;

        while (left <= right) {
            if (intArray[left] < pivot) {
                left++;
            } else if (intArray[right] > pivot) {
                right--;
            } else {
                // Troca elementos
                int temp = intArray[left];
                intArray[left] = intArray[right];
                intArray[right] = temp;
                left++;
                right--;
            }
        }

        // Coloca o pivot na posição correta
        int temp = intArray[0];
        intArray[0] = intArray[left - 1];
        intArray[left - 1] = temp;

        System.out.println(cont);
    }
}
