        }

        List<Integer> result = tree.rightToLeftBFS();

        // Imprime em ordem reversa para obter direita para esquerda
        for (int i = result.size() - 1; i >= 0; i--) {
            System.out.print(result.get(i));
            if (i > 0) System.out.print(" ");
        }
        System.out.println();
    }
