import java.util.*;

public class Solution {

    static class Node {
        int value;
        Node left, right;
        Node(int v) { value = v; }
    }

    static Node insert(Node root, int v) {
        if (root == null) return new Node(v);
        if (v < root.value) root.left = insert(root.left, v);
        else root.right = insert(root.right, v);
        return root;
    }

    static void preOrder(Node root, List<Integer> out) {
        if (root == null) return;
        out.add(root.value);
        preOrder(root.left, out);
        preOrder(root.right, out);
    }

    static int countLess(Node root, int n) {
        if (root == null) return 0;
        if (root.value < n)
            return 1 + countLess(root.left, n) + countLess(root.right, n);
        else
            return countLess(root.left, n);
    }

    public static void main(String[] args) {
